INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 0.0, 24, 4, 0.0, 24015, 4, 10021, 0.0, 1, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 0.0, 24, 4, 4.0, 24016, 1, 10021, 0.0, 2, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("マジムンだらけで目が回るさ～！\nふらふらさ～！", 0.0, 24, 4, 0.0, 24017, 4, 10021, 0.0, 3, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 0.0, 24, 1, 5.2, 24018, 2, 10021, 0.0, 4, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 0.0, 24, 5, 4.2, 24019, 6, 10021, 0.0, 5, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 0.0, 24, 2, 0.0, 24020, 2, 10021, 0.0, 6, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 0.0, 24, 1, 6.4, 24021, 6, 10021, 0.0, 7, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 0.0, 24, 2, 0.0, 24022, 2, 10021, 0.0, 8, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 0.0, 24, 6, 10.08, 24023, 3, 10021, 0.0, 9, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 0.0, 24, 1, 5.0, 24024, 2, 10021, 0.0, 10, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 0.0, 24, 2, 0.0, 24025, 2, 10021, 0.0, 11, "2019/07/31 12:00:00", "2030/12/17 14:59:59", 110501, "カオリ（サマー）");
